class Solution {
public:
    int minimumJumps(vector<int>& forbidden, int a, int b, int x) {
        unordered_set<int> banned(forbidden.begin(), forbidden.end());
        int limit = max(x, *max_element(forbidden.begin(), forbidden.end())) + a + b;
        vector<array<bool, 2>> seen(limit + 1);
        queue<array<int, 3>> q;
        q.push({0, 0, 0});
        seen[0][0] = true;
        while (!q.empty()) {
            auto [pos, back, steps] = q.front();
            q.pop();
            if (pos == x) return steps;
            int fwd = pos + a;
            if (fwd <= limit && !banned.count(fwd) && !seen[fwd][0]) {
                seen[fwd][0] = true;
                q.push({fwd, 0, steps + 1});
            }
            int bwd = pos - b;
            if (!back && bwd >= 0 && !banned.count(bwd) && !seen[bwd][1]) {
                seen[bwd][1] = true;
                q.push({bwd, 1, steps + 1});
            }
        }
        return -1;
    }
};

