class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> banned = new HashSet<>();
        int mx = 0;
        for (int f : forbidden) {
            banned.add(f);
            mx = Math.max(mx, f);
        }
        int limit = Math.max(mx, x) + a + b;
        boolean[][] seen = new boolean[limit + 1][2];
        Deque<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{0, 0, 0});
        seen[0][0] = true;
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int pos = cur[0], back = cur[1], steps = cur[2];
            if (pos == x) return steps;
            int fwd = pos + a;
            if (fwd <= limit && !banned.contains(fwd) && !seen[fwd][0]) {
                seen[fwd][0] = true;
                queue.offer(new int[]{fwd, 0, steps + 1});
            }
            int bwd = pos - b;
            if (back == 0 && bwd >= 0 && !banned.contains(bwd) && !seen[bwd][1]) {
                seen[bwd][1] = true;
                queue.offer(new int[]{bwd, 1, steps + 1});
            }
        }
        return -1;
    }
}

