class Solution {
public:
    int minimumJumps(vector<int>& forbidden, int a, int b, int x) {
        unordered_set<int> banned(forbidden.begin(), forbidden.end());
        int limit = max(x, *max_element(forbidden.begin(), forbidden.end())) + a + b;
        const long long INF = LLONG_MAX;
        vector<array<long long, 2>> dist(limit + 1, {INF, INF});
        deque<pair<int, int>> dq;
        dist[0][0] = 0;
        dq.emplace_back(0, 0);
        while (!dq.empty()) {
            auto [pos, d] = dq.front();
            dq.pop_front();
            long long base = dist[pos][d];
            long long fwd = pos + a;
            if (fwd <= limit && !banned.count((int)fwd) && base + 1 < dist[fwd][0]) {
                dist[fwd][0] = base + 1;
                dq.emplace_back((int)fwd, 0);
            }
            long long bwd = pos - b;
            if (d == 0 && bwd >= 0 && !banned.count((int)bwd) && base + 1 < dist[bwd][1]) {
                dist[bwd][1] = base + 1;
                dq.emplace_back((int)bwd, 1);
            }
        }
        long long ans = min(dist[x][0], dist[x][1]);
        return ans == INF ? -1 : (int)ans;
    }
};

