class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        Set<Integer> banned = new HashSet<>();
        int mx = 0;
        for (int f : forbidden) {
            banned.add(f);
            mx = Math.max(mx, f);
        }
        int limit = Math.max(mx, x) + a + b;
        long[][] dist = new long[limit + 1][2];
        for (long[] row : dist) Arrays.fill(row, Long.MAX_VALUE);
        Deque<int[]> dq = new ArrayDeque<>();
        dist[0][0] = 0;
        dq.add(new int[]{0, 0});
        while (!dq.isEmpty()) {
            int[] top = dq.poll();
            int pos = top[0], d = top[1];
            long base = dist[pos][d];
            long fwd = pos + a;
            if (fwd <= limit && !banned.contains((int) fwd) && base + 1 < dist[(int) fwd][0]) {
                dist[(int) fwd][0] = base + 1;
                dq.add(new int[]{(int) fwd, 0});
            }
            long bwd = pos - b;
            if (d == 0 && bwd >= 0 && !banned.contains((int) bwd) && base + 1 < dist[(int) bwd][1]) {
                dist[(int) bwd][1] = base + 1;
                dq.add(new int[]{(int) bwd, 1});
            }
        }
        long ans = Math.min(dist[x][0], dist[x][1]);
        return ans == Long.MAX_VALUE ? -1 : (int) ans;
    }
}

